"""The /api/* token gate: generated by default, TRACKER_API_TOKEN overrides.

Loopback is not an identity — every local process can reach 127.0.0.1 — so the
token is generated on startup when the env var is unset, persisted 0600 under
the user config dir, and handed to the dashboard only on a same-origin,
loopback render of the page.
"""

import os
import stat
from pathlib import Path

import pytest


@pytest.fixture()
def app_module(tmp_path, monkeypatch):
    import app as module

    monkeypatch.setattr(module, "DB_PATH", tmp_path / "token.db")
    monkeypatch.setattr(module, "CSV_PATH", tmp_path / "token.csv")
    monkeypatch.setattr(module, "PERIOD_START_DAY", 1)
    module.app.config.update(TESTING=True)
    return module


@pytest.fixture()
def client(app_module):
    with app_module.app.test_client() as test_client:
        yield test_client


def token_file(app_module) -> Path:
    return app_module._config_dir() / app_module.API_TOKEN_FILENAME


def test_no_env_var_generates_a_token_and_gates_api(app_module, client):
    # The default deploy has no TRACKER_API_TOKEN: loopback still gets a 401.
    app_module.API_TOKEN = ""
    assert client.get("/api/profiles").status_code == 401

    path = token_file(app_module)
    assert path.is_file(), "the generated token must be persisted"
    token = path.read_text(encoding="utf-8").strip()
    assert len(token) == 43, "32 random bytes -> 43 URL-safe characters"

    res = client.get("/api/profiles", headers={"X-Tracker-Token": token})
    assert res.status_code == 200


def test_generated_token_is_reused_on_the_next_start(app_module, monkeypatch):
    app_module.API_TOKEN = ""
    first, path, created = app_module.load_or_create_token()
    assert created is True
    # Simulate a restart: a fresh process reads the persisted token.
    monkeypatch.setattr(app_module, "API_TOKEN", "")
    second, same_path, created_again = app_module.load_or_create_token()
    assert created_again is False
    assert first == second
    assert path == same_path


def test_generated_token_is_printed_once_with_a_pointer(app_module, capsys):
    app_module.API_TOKEN = ""
    token = app_module.api_token()
    app_module.api_token()  # every later request must not re-print the secret
    out = capsys.readouterr().out
    assert out.count(token) == 1
    assert "TRACKER_API_TOKEN" in out
    assert app_module.API_TOKEN_FILENAME in out


def test_persisted_token_file_is_owner_only(tmp_path, monkeypatch):
    import app as module

    opened = []
    chmods = []
    real_open, real_chmod = os.open, os.chmod

    def spy_open(path, flags, mode=0o777, *args, **kwargs):
        opened.append((Path(path), flags, mode))
        return real_open(path, flags, mode, *args, **kwargs)

    def spy_chmod(path, mode, *args, **kwargs):
        chmods.append((Path(path), mode))
        return real_chmod(path, mode, *args, **kwargs)

    monkeypatch.setattr(module.os, "open", spy_open)
    monkeypatch.setattr(module.os, "chmod", spy_chmod)

    token, path, created = module.load_or_create_token(tmp_path / "cfg")
    assert created is True
    assert path.read_text(encoding="utf-8").strip() == token
    assert [(flags, mode) for _, flags, mode in opened] == [
        (os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    ]
    assert [mode for _, mode in chmods] == [0o600]
    if os.name == "posix":
        assert stat.S_IMODE(path.stat().st_mode) == 0o600


def test_env_override_wins_and_creates_no_file(app_module, client, monkeypatch):
    app_module.API_TOKEN = "ci-token"
    assert client.get("/api/profiles").status_code == 401
    res = client.get("/api/profiles", headers={"X-Tracker-Token": "ci-token"})
    assert res.status_code == 200
    assert not token_file(app_module).exists()


def test_health_is_always_reachable(app_module, client):
    app_module.API_TOKEN = "s3cret-token"
    # Probes and the watchdog must not need a credential.
    assert client.get("/api/health").status_code == 200


def test_empty_or_wrong_token_is_rejected(app_module, client):
    app_module.API_TOKEN = "s3cret-token"
    assert client.get("/api/profiles", headers={"X-Tracker-Token": ""}).status_code == 401
    assert client.get("/api/profiles", headers={"X-Tracker-Token": "nope"}).status_code == 401
    assert client.get("/api/profiles", headers={"X-Tracker-Token": "s3cret-tokem"}).status_code == 401


def test_header_and_query_token_are_accepted(app_module, client):
    app_module.API_TOKEN = "s3cret-token"
    assert client.get("/api/profiles", headers={"X-Tracker-Token": "s3cret-token"}).status_code == 200
    assert client.get("/api/profiles?token=s3cret-token").status_code == 200


def test_state_changing_route_is_gated_too(app_module, client):
    app_module.API_TOKEN = "s3cret-token"
    res = client.post("/api/plan", json={"plan": "go"})
    assert res.status_code == 401
    res = client.post(
        "/api/plan",
        json={"plan": "go"},
        headers={"X-Tracker-Token": "s3cret-token"},
    )
    assert res.status_code != 401


def test_routes_that_spend_the_server_key_need_the_token(app_module, client, monkeypatch):
    """The OPENCODE_API_KEY routes must not be reachable without the token."""
    # Default deploy: no TRACKER_API_TOKEN, token generated on first use.
    app_module.API_TOKEN = ""
    monkeypatch.setenv("OPENCODE_API_KEY", "oc_sk_server_key_not_real")

    def boom(*args, **kwargs):  # pragma: no cover - must never run
        raise AssertionError("gate bypassed: request reached the handler")

    monkeypatch.setattr(app_module, "OpencodeLogger", boom)
    monkeypatch.setattr(app_module, "check_key", boom)
    monkeypatch.setattr(app_module, "sync_limits", boom)
    monkeypatch.setattr(app_module, "import_sessions", boom)

    calls = [
        ("/api/log", {"model": "kimi-k3", "message": "hi"}),
        ("/api/key-check", {}),
        ("/api/sync-limits", {}),
        ("/api/import-sessions", {}),
    ]
    for path, body in calls:
        res = client.post(path, json=body)
        assert res.status_code == 401, path
        assert "token" in res.get_json()["error"].lower(), path


def test_token_lets_the_spending_route_reach_its_handler(app_module, client, monkeypatch):
    app_module.API_TOKEN = "s3cret-token"

    class FakeLogger:
        def __init__(self, *args, **kwargs):
            raise RuntimeError("handler reached")

    monkeypatch.setattr(app_module, "OpencodeLogger", FakeLogger)
    res = client.post(
        "/api/log",
        json={"model": "kimi-k3", "message": "hi", "api_key": "oc_sk_test"},
        headers={"X-Tracker-Token": "s3cret-token"},
    )
    # 400 comes from the handler, i.e. the guard let the request through.
    assert res.status_code == 400
    assert "handler reached" in res.get_json()["error"]


def test_dashboard_is_served_the_token(app_module, client):
    app_module.API_TOKEN = ""
    res = client.get("/")
    assert res.status_code == 200
    token = token_file(app_module).read_text(encoding="utf-8").strip()
    body = res.data.decode("utf-8")
    assert f'<meta name="tracker-api-token" content="{token}"/>' in body
    # The page must send it, or the dashboard would 401 on every tab.
    assert "X-Tracker-Token" in body


def test_dashboard_does_not_leak_the_token_off_origin(app_module, client):
    app_module.API_TOKEN = "s3cret-token"
    assert b'<meta name="tracker-api-token" content="s3cret-token"/>' in client.get("/").data

    foreign = client.get("/", headers={"Host": "evil.example:8000"})
    assert b"s3cret-token" not in foreign.data

    remote = client.get("/", environ_overrides={"REMOTE_ADDR": "192.168.1.20"})
    assert b"s3cret-token" not in remote.data


def test_daemon_startup_generates_the_token(tmp_path, monkeypatch):
    """`opencode-tracker daemon` serves the same app; it must gate it too."""
    import app as module
    from opencode_tracker.daemon import load_web_app

    monkeypatch.setattr(module, "API_TOKEN", "")
    monkeypatch.setattr(module, "_TOKEN_PRINTED", False)
    original = (module.DB_PATH, module.CSV_PATH, module.PERIOD_START_DAY)
    try:
        load_web_app(tmp_path / "daemon.db", tmp_path / "daemon.csv", 1)
        assert module.API_TOKEN
        assert token_file(module).is_file()
    finally:
        module.DB_PATH, module.CSV_PATH, module.PERIOD_START_DAY = original
